record_types.code:
type HLR_Info is record
   Id     : String (1 .. Types.Max_Id_Str);
   Id_Len : Natural := 0;
   Desc   : String (1 .. Types.Max_Desc_Str);
   D_Len  : Natural := 0;
end record;

type LLR_Info is record
   Id      : String (1 .. Types.Max_Id_Str);
   Id_Len  : Natural := 0;
   HLR_Ref : String (1 .. Types.Max_Id_Str);
   HLR_Len : Natural := 0;
   Desc    : String (1 .. Types.Max_Desc_Str);
   D_Len   : Natural := 0;
end record;

